/**
 * Spider UI — static asset regression tests.
 *
 * These tests verify the HTML structure generated by spider.js for the rig
 * list table.  Because spider.js is a vanilla-JS IIFE (no modules), we
 * validate the source text directly to ensure structural invariants hold.
 *
 * Helpers:
 *   has(s, re)         — assert s matches re
 *   lacks(s, re)       — assert s does NOT match re
 *   fnBody(name, end?) — slice the body of `function name(…)` from spiderJs
 *                        up to `end` (default: the next `\n  function `)
 *   idDecl(id)         — RegExp matching `id="<id>"`
 */

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const spiderJs = readFileSync(resolve(__dirname, 'spider.js'), 'utf-8');
const spiderCss = readFileSync(resolve(__dirname, 'spider.css'), 'utf-8');
const indexHtml = readFileSync(resolve(__dirname, 'index.html'), 'utf-8');

const has = (s: string, re: RegExp) => assert.match(s, re);
const lacks = (s: string, re: RegExp) => assert.doesNotMatch(s, re);
const idDecl = (id: string) => new RegExp(`id="${id}"`);
const fnBody = (name: string, end: RegExp = /\n  function /): string => {
  const re = new RegExp(`function ${name}\\([^)]*\\)[\\s\\S]*?(?=${end.source})`);
  const m = spiderJs.match(re);
  assert.ok(m, `should find function ${name}`);
  return m[0];
};

describe('spider.js rig list row HTML', () => {
  // After the keyed in-place refactor, rig rows are assembled by
  // createRigRow via document.createElement rather than an HTML template.
  // Both writ-title and rig-id cells are built as rig-link anchors; the
  // writ-title cell is never a plain <td> of text.
  const createRigRow = fnBody('createRigRow', /return tr;\s*\}/);

  it('renders the writ-title cell as a rig-link anchor', () => {
    has(createRigRow, /writTitleAnchor\s*=\s*document\.createElement\(['"]a['"]\)/);
    has(createRigRow, /writTitleAnchor\.className\s*=\s*['"]rig-link['"]/);
    has(createRigRow, /writTitleAnchor\.setAttribute\(['"]data-rig-id['"]\s*,\s*rig\.id\)/);
  });

  it('renders the rig-id cell as a rig-link anchor', () => {
    has(createRigRow, /rigIdAnchor\s*=\s*document\.createElement\(['"]a['"]\)/);
    has(createRigRow, /rigIdAnchor\.className\s*=\s*['"]rig-link['"]/);
    has(createRigRow, /rigIdAnchor\.textContent\s*=\s*rig\.id/);
  });

  it('writ-title and rig-id cells share the same rig-link class', () => {
    const rigLinkCount = (createRigRow.match(/['"]rig-link['"]/g) || []).length;
    assert.ok(rigLinkCount >= 2, `expected at least 2 rig-link anchors, found ${rigLinkCount}`);
  });

  it('writ-title cell is NOT rendered as plain text', () => {
    // Regression guard: writ-title cell must always be an anchor, never a
    // plain text <td>. Forbid the legacy string-template shape and any
    // direct textContent assignment of the writ title.
    lacks(spiderJs, /'<td>'\s*\+\s*esc\(writTitle\)\s*\+\s*'<\/td>'/);
    lacks(spiderJs, /writTitleTd\.textContent\s*=\s*writTitle/);
  });

  it('writ deep-links target the canonical Clerk writs page path', () => {
    // Historically the writ-id anchors targeted '/pages/clerk/?writ=…',
    // but no plugin registers a 'clerk' page — the writs page is served
    // at '/pages/writs/'. The broken URL produced a bare 404 on every
    // click. Pin the canonical shape (matches the Ratchet linkDispatch
    // helper) and forbid the broken one.
    has(spiderJs, /\/pages\/writs\/\?writ=/);
    lacks(spiderJs, /\/pages\/clerk\/\?writ=/);
  });
});

describe('spider.js cancel button', () => {
  it('renders a cancel button with id "cancel-engine-btn"', () => {
    has(spiderJs, /id="cancel-engine-btn"/);
  });

  it('cancel button has btn--danger class', () => {
    has(spiderJs, /class="btn btn--danger" id="cancel-engine-btn"/);
  });

  it('cancel button sends POST to /api/rig/cancel', () => {
    has(spiderJs, /method:\s*'POST'/);
    has(spiderJs, /\/api\/rig\/cancel/);
  });

  it('cancel button is conditional on rig status running', () => {
    // After the engine-level retry reshape, `rig.status === 'blocked'`
    // no longer exists as a live status — an engine held on a retry
    // timer or external gate is `pending` while the rig stays
    // `running`. The cancel button's visibility therefore gates on
    // `running` alone.
    has(spiderJs, /currentRig\.status === 'running'/);
  });

  it('cancel button is hidden for terminal rig statuses', () => {
    has(spiderJs, /currentRig\.status === 'cancelled'/);
  });

  it('cancel button does NOT use DELETE method', () => {
    // DELETE with JSON body is unreliable across HTTP stacks; cancel
    // fetch must use POST to match the auto-generated tool route.
    const cancelFetch = spiderJs.match(/fetch\('\/api\/rig\/cancel'[\s\S]*?\)/);
    assert.ok(cancelFetch, 'should find the cancel fetch call');
    lacks(cancelFetch[0], /method:\s*'DELETE'/);
  });

  it('cancel handler uses the cancel API response directly (no redundant rig-show fetch)', () => {
    const cancelChain = spiderJs.match(/fetch\('\/api\/rig\/cancel'[\s\S]*?\.catch/);
    assert.ok(cancelChain, 'should find the cancel fetch chain');
    lacks(cancelChain[0], /fetch\('\/api\/rig\/show/);
  });

  it('cancel handler calls preventDefault on click event', () => {
    has(spiderJs, /addEventListener\('click', function \(e\)[\s\S]*?e\.preventDefault\(\)/);
  });
});

describe('spider.js badgeClass for cancelled', () => {
  it('badgeClass returns "badge--cancelled" for cancelled status', () => {
    has(spiderJs, /case 'cancelled':\s*return 'badge--cancelled'/);
  });

  it('cancelled is not grouped with pending in badgeClass', () => {
    lacks(spiderJs, /case 'pending':\s*case 'cancelled'/);
  });
});

