describe('index.html status filter post-reshape options', () => {
  // After the engine/rig status reshape (commission moeqpd6g), the rig
  // status enum is `running | completed | failed | cancelled`. The legacy
  // `'stuck'` and `'blocked'` <option> tags were removed — operators
  // inspecting persisted legacy rigs go through the CLI escape hatch
  // (`nsg rig-list --status=stuck`) instead.

  it('status filter has cancelled option', () => {
    has(indexHtml, /<option value="cancelled">cancelled<\/option>/);
  });

  it('status filter does NOT include the legacy stuck option', () => {
    lacks(indexHtml, /<option value="stuck">/);
  });

  it('status filter does NOT include the legacy blocked option', () => {
    lacks(indexHtml, /<option value="blocked">/);
  });

  it('status filter enumerates exactly the four current rig values plus all', () => {
    const expected = ['', 'running', 'completed', 'failed', 'cancelled'];
    const slice = indexHtml.match(/<select id="status-filter">([\s\S]*?)<\/select>/);
    assert.ok(slice, 'should find the status-filter <select> block');
    const observed: string[] = [];
    const optionRe = /<option value="([^"]*)">/g;
    let m;
    while ((m = optionRe.exec(slice[1])) !== null) observed.push(m[1]);
    assert.deepStrictEqual(observed, expected);
  });
});

describe('spider.js rig list polling', () => {
  it('declares rigListPollTimer state variable', () => {
    has(spiderJs, /var rigListPollTimer\s*=\s*null/);
  });

  it('declares currentRigPollTimer state variable', () => {
    has(spiderJs, /var currentRigPollTimer\s*=\s*null/);
  });

  it('declares RIG_POLL_INTERVAL constant', () => {
    has(spiderJs, /var RIG_POLL_INTERVAL\s*=\s*2000/);
  });

  it('defines isRigInFlight helper checking only running (no legacy blocked)', () => {
    // Post-reshape: 'running' is the only non-terminal rig status. The
    // legacy `'blocked'` value is no longer honored as in-flight — it
    // was a hold expressed at the rig level, which the engine-retry
    // commission moved off the rig and onto pending engines via
    // holdReason / holdUntil / attemptCount.
    has(spiderJs, /function isRigInFlight\(rig\)/);
    const body = fnBody('isRigInFlight', /\n  \}/);
    has(body, /rig\.status === 'running'/);
    lacks(body, /'blocked'/);
    lacks(body, /'stuck'/);
  });

  it('isRigTerminal preserves the deliberate single-value stuck tolerance (D3)', () => {
    // D3 / asymmetric tolerance: dropping `'stuck'` from isRigTerminal
    // would leave a legacy `'stuck'` rig polling indefinitely (neither
    // in-flight per isRigInFlight, nor terminal). The asymmetry between
    // these two helpers is deliberate; pin it so a future cleanup pass
    // does not silently align them.
    const body = fnBody('isRigTerminal', /\n  \}/);
    has(body, /'stuck'/);
    lacks(body, /'blocked'/);
  });

  it('defines stopRigListPoll that clears the interval', () => {
    has(spiderJs, /function stopRigListPoll\(\)/);
    has(spiderJs, /clearInterval\(rigListPollTimer\)/);
  });

  it('defines stopCurrentRigPoll that clears the interval', () => {
    has(spiderJs, /function stopCurrentRigPoll\(\)/);
    has(spiderJs, /clearInterval\(currentRigPollTimer\)/);
  });

  it('starts rig list polling after fetchRigs succeeds', () => {
    const fetchRigs = spiderJs.match(/function fetchRigs\([\s\S]*?\.catch/);
    assert.ok(fetchRigs, 'should find fetchRigs function');
    has(fetchRigs[0], /startRigListPollIfNeeded\(\)/);
  });

  it('starts current rig polling in showRigDetail', () => {
    has(spiderJs, /function showRigDetail\(rig(?:, opts)?\)[\s\S]*?startCurrentRigPoll\(\)/);
  });

  it('stops current rig poll when navigating back to list', () => {
    has(spiderJs, /function backToList\((?:opts)?\)[\s\S]*?stopCurrentRigPoll\(\)/);
  });

  it('stops current rig poll when selecting a new rig', () => {
    has(spiderJs, /function showRigDetail\(rig(?:, opts)?\)[\s\S]*?stopCurrentRigPoll\(\)/);
  });

  it('fetchCurrentRigQuiet fetches /api/rig/show with rig id', () => {
    has(spiderJs, /function fetchCurrentRigQuiet\(\)/);
    has(spiderJs, /\/api\/rig\/show\?id=/);
  });

  it('fetchCurrentRigQuiet preserves selectedEngineId across polls', () => {
    has(fnBody('fetchCurrentRigQuiet'), /selectedEngineId/);
  });

  it('fetchCurrentRigQuiet stops polling on terminal status', () => {
    has(fnBody('fetchCurrentRigQuiet'), /isRigInFlight/);
  });

  it('refresh button resets rig list poll cycle', () => {
    const refresh = spiderJs.match(/refresh-btn[\s\S]*?fetchRigs/);
    assert.ok(refresh, 'should find refresh button handler');
    has(refresh[0], /stopRigListPoll\(\)/);
  });

  it('rig list quiet poll stops itself when no in-flight rigs remain', () => {
    const quiet = spiderJs.match(/function fetchRigListQuiet[\s\S]*?stopRigListPoll/);
    assert.ok(quiet, 'should find fetchRigListQuiet');
    has(quiet[0], /hasInFlight/);
  });
});

describe('spider.js engine-detail stable-skeleton + updater', () => {
  it('defines updateEngineDetail as a separate function from showEngineDetail', () => {
    has(spiderJs, /function updateEngineDetail\(engine\)/);
    has(spiderJs, /function showEngineDetail\(engine\)/);
  });

  it('defines a buildEngineDetailSkeleton that establishes stable field ids', () => {
    has(spiderJs, /function buildEngineDetailSkeleton\(/);
  });

  it('skeleton declares stable id containers for the value-bearing fields', () => {
    // Per T6/D14 the three old cost rows (ed-cost-input / ed-cost-output /
    // ed-cost-usd) were collapsed into a single `ed-cost` row driven by
    // the enriched rig view. Per the post-reshape refresh (commission
    // moeqpd6g) the legacy `ed-block-*` ids were renamed to `ed-hold-*`
    // and the dead Block Message row was removed.
    const expectedIds = [
      'ed-status', 'ed-design-id', 'ed-upstream', 'ed-started-at',
      'ed-completed-at', 'ed-elapsed', 'ed-error', 'ed-session-id',
      'ed-hold-reason', 'ed-cost', 'ed-givens-code', 'ed-yields-code',
      'ed-cancel-container',
    ];
    for (const id of expectedIds) has(spiderJs, idDecl(id));
  });

  it('skeleton renames legacy ed-block-* ids to ed-hold-* and drops Block Message', () => {
    // Post-reshape (commission moeqpd6g): the engine-detail panel uses
    // hold terminology to match the engine.holdReason / holdUntil /
    // lastCheckedAt / holdCondition record fields. The dead Block
    // Message row (no caller, no consumer) was dropped entirely (D11).
    const newIds = [
      'ed-hold-reason', 'ed-hold-until', 'ed-hold-last-checked',
      'ed-hold-condition', 'ed-hold-condition-pre',
    ];
    for (const id of newIds) has(spiderJs, idDecl(id));

    const removedIds = [
      'ed-block-type', 'ed-block-blocked-at', 'ed-block-message',
      'ed-block-last-checked', 'ed-block-condition', 'ed-block-condition-pre',
    ];
    for (const id of removedIds) lacks(spiderJs, idDecl(id));

    // Dead Block Message row labels and the dt are gone.
    for (const label of ['Block Type', 'Blocked At', 'Block Message', 'Block Condition']) {
      lacks(spiderJs, new RegExp(`>${label}<`));
    }
    // New labels are present.
    for (const label of ['Hold Reason', 'Held Until', 'Last Checked', 'Hold Condition']) {
      has(spiderJs, new RegExp(`>${label}<`));
    }
  });

  it('no longer declares the legacy three-row cost skeleton', () => {
    // T6 / D14 regression guard. The engine-detail panel now uses a single
    // #ed-cost row; the old ed-cost-input/output/usd trio must not return.
    for (const legacyId of ['ed-cost-input', 'ed-cost-output', 'ed-cost-usd']) {
      lacks(spiderJs, idDecl(legacyId));
    }
  });

  it('engine-detail single cost row is fed from currentRig.engineCosts[engine.id]', () => {
    // T6 / D18: no per-engine /api/session/show fetch; the cost value for
    // the selected engine is read straight off the enriched rig payload.
    const body = fnBody('updateEngineDetail');
    has(body, /currentRig\.engineCosts\s*\)\s*\?\s*currentRig\.engineCosts\[engine\.id\]/);
    has(body, /setText\(['"]ed-cost['"]\s*,\s*window\.NexusFormat\.formatCostWithTokens\(/);
    has(body, /setRowDisplay\(['"]ed-cost-dt['"]\s*,\s*['"]ed-cost['"]\s*,\s*true\)/);
    has(body, /setRowDisplay\(['"]ed-cost-dt['"]\s*,\s*['"]ed-cost['"]\s*,\s*false\)/);
  });

  it('the old #cost-placeholder insertAdjacentHTML trick is gone', () => {
    lacks(spiderJs, /id="cost-placeholder"/);
    lacks(spiderJs, /insertAdjacentHTML\('beforebegin'/);
  });

  it('the rig poll path calls updateEngineDetail (not showEngineDetail) for the selected engine', () => {
    const body = fnBody('fetchCurrentRigQuiet');
    has(body, /updateEngineDetail\(/);
    // showEngineDetail would re-open SSE and rebuild the panel.
    lacks(body, /showEngineDetail\(/);
  });

  it('updateEngineDetail does not rewrite the engine-detail-body innerHTML', () => {
    lacks(fnBody('updateEngineDetail'), /engine-detail-body[\s\S]*?innerHTML\s*=/);
  });
});

describe('spider.js SSE removal', () => {
  // The SSE path was removed because animator.subscribeToSession does not
  // work across processes (detached sessions return null). The UI now
  // polls /api/spider/session-transcript uniformly for all sessions.
  // These guards keep the SSE code from creeping back in.

  it('has no EventSource constructor in the UI code', () => {
    lacks(spiderJs, /new\s+EventSource/);
  });

  it('does not define streamSessionId or streamDone state', () => {
    lacks(spiderJs, /\bstreamSessionId\b/);
    lacks(spiderJs, /\bstreamDone\b/);
  });

  it('does not define ensureSessionStream / openSessionStream / stopSessionStream', () => {
    lacks(spiderJs, /function\s+ensureSessionStream/);
    lacks(spiderJs, /function\s+openSessionStream/);
    lacks(spiderJs, /function\s+stopSessionStream/);
  });

  it('does not reference /api/spider/session-stream', () => {
    lacks(spiderJs, /\/api\/spider\/session-stream/);
  });
});

describe('spider.js session transcript polling', () => {
  it('declares transcriptPollSessionId in module scope', () => {
    has(spiderJs, /var transcriptPollSessionId\s*=\s*null/);
  });

  it('declares TRANSCRIPT_POLL_INTERVAL at 2000 ms', () => {
    has(spiderJs, /var TRANSCRIPT_POLL_INTERVAL\s*=\s*2000/);
  });

  it('defines startSessionTranscriptPoll that dedupes on sessionId', () => {
    has(spiderJs, /function startSessionTranscriptPoll\(/);
    has(fnBody('startSessionTranscriptPoll'), /sessionId\s*===\s*transcriptPollSessionId/);
  });

  it('defines stopSessionTranscriptPoll that clears transcriptPollSessionId', () => {
    has(spiderJs, /function stopSessionTranscriptPoll\(/);
    const body = fnBody('stopSessionTranscriptPoll');
    has(body, /transcriptPollSessionId\s*=\s*null/);
    has(body, /stopSessionPoll\(/);
  });

  it('defines fetchAndRenderTranscript that calls /api/spider/session-transcript', () => {
    has(spiderJs, /function fetchAndRenderTranscript\(/);
    has(fnBody('fetchAndRenderTranscript'), /\/api\/spider\/session-transcript\?sessionId=/);
  });

  it('fetchAndRenderTranscript stops polling on terminal session status', () => {
    has(fnBody('fetchAndRenderTranscript'), /stopSessionTranscriptPoll\(/);
  });

  it('fetchAndRenderTranscript captures atBottom before replacing textarea value', () => {
    const body = fnBody('fetchAndRenderTranscript');
    has(body, /var atBottom\s*=/);
    has(body, /if\s*\(atBottom\)/);
  });

  it('updateEngineDetail drives transcript polling via startSessionTranscriptPoll', () => {
    // dedup handles repeated start calls every poll.
    has(fnBody('updateEngineDetail'), /startSessionTranscriptPoll\(/);
  });

  it('navigating away stops transcript polling via resetSessionLog', () => {
    // T7: the canonical tear-down is now resetSessionLog(), which wraps
    // stopSessionTranscriptPoll(). Both backToList and showRigDetail
    // route through that helper so the textarea + spinner state is
    // cleared alongside the poll.
    has(fnBody('backToList'), /resetSessionLog\(/);
    has(fnBody('showRigDetail'), /resetSessionLog\(/);
  });
});

describe('spider.js elapsed ticker', () => {
  it('declares elapsedTimer and elapsedTimerStartedAt in module scope', () => {
    has(spiderJs, /var elapsedTimer\s*=\s*null/);
    has(spiderJs, /var elapsedTimerStartedAt\s*=\s*null/);
  });

  it('declares ELAPSED_TICK_INTERVAL at 1000 ms', () => {
    has(spiderJs, /var ELAPSED_TICK_INTERVAL\s*=\s*1000/);
  });

  it('defines startElapsedTimer that dedupes on startedAt', () => {
    has(spiderJs, /function startElapsedTimer\(/);
    const body = fnBody('startElapsedTimer');
    has(body, /elapsedTimerStartedAt\s*===\s*startedAt/);
    has(body, /formatElapsed\(startedAt,\s*new Date\(\)\.toISOString\(\)\)/);
  });

  it('defines stopElapsedTimer that clears the interval', () => {
    has(spiderJs, /function stopElapsedTimer\(/);
    has(fnBody('stopElapsedTimer'), /clearInterval\(elapsedTimer\)/);
  });

  it('updateEngineDetail starts the ticker for running engines with an attempt start', () => {
    // After the engine-level retry reshape, engine-level `startedAt` no
    // longer exists — the attempt's startedAt lives on `attempts[-1]`.
    // The UI reads it via a local derived from `latestAttempt(engine)`;
    // the ticker start gates on engine.status === 'running' and a
    // non-null attempt start.
    has(
      fnBody('updateEngineDetail'),
      /engine\.status\s*===\s*'running'\s*&&\s*attemptStartedAt[\s\S]*?startElapsedTimer\(/,
    );
  });

  it('updateEngineDetail stops the ticker when engine completes', () => {
    has(
      fnBody('updateEngineDetail'),
      /engine\.status\s*===\s*'completed'[\s\S]*?stopElapsedTimer\(/,
    );
  });

  it('static "running…" placeholder is replaced by the live ticker', () => {
    // The old implementation wrote a literal "running…" span. The ticker
    // now writes a live elapsed value every second.
    lacks(spiderJs, /<span class="elapsed-running">running\\u2026<\/span>/);
  });

  it('navigating away stops the elapsed ticker', () => {
    has(fnBody('backToList'), /stopElapsedTimer\(/);
    has(fnBody('showRigDetail'), /stopElapsedTimer\(/);
  });
});

describe('spider.js pipeline keyed update', () => {
  it('renderPipelineInto indexes existing nodes by data-engine-id', () => {
    const body = fnBody('renderPipelineInto');
    has(body, /querySelectorAll\(['"]\.pipeline-node['"]\)/);
    has(body, /getAttribute\(['"]data-engine-id['"]\)/);
  });

  it('renderPipelineInto has a fast path that patches in place when order is unchanged', () => {
    has(fnBody('renderPipelineInto'), /orderUnchanged/);
  });

  it('exposes updatePipelineNode for in-place badge/selection updates', () => {
    has(spiderJs, /function updatePipelineNode\(node, engine\)/);
  });

  it('pipeline node carries a class hook for the status badge', () => {
    // Without a class hook, the keyed-update path can't unambiguously
    // target the status badge inside a node.
    has(spiderJs, /pipeline-node-status/);
  });

  it('createPipelineNode appends a hold sub-badge element below the status badge', () => {
    // Post-reshape (commission moeqpd6g, D6): the pipeline-node carries
    // a conditional secondary badge that surfaces holdReason /
    // attemptCount on pending engines, so operators see retry state
    // at-a-glance without clicking through to the engine-detail panel.
    // Mirrors .pipeline-node-upstream conditional-display lifecycle:
    // always present, display-toggled via inline style. Reuses an
    // existing oculus badge variant (badge--info or badge--warning) —
    // no new CSS.
    const body = fnBody('createPipelineNode');
    has(body, /pipeline-node-hold/);
    has(body, /badge--info|badge--warning/);
    has(body, /holdEl\.style\.display\s*=\s*['"]none['"]/);
  });

  it('updatePipelineNode shows the hold sub-badge on pending engines with hold metadata', () => {
    // D10: the gate is OR — render whenever the engine is pending and
    // either holdReason or attemptCount is set. External-gate holds
    // (e.g. animator-paused) are operationally as significant as
    // retry holds.
    const body = fnBody('updatePipelineNode');
    has(body, /pipeline-node-hold/);
    has(body, /engine\.status === 'pending'\s*&&\s*\(engine\.holdReason\s*\|\|\s*engine\.attemptCount\)/);
    has(body, /\(attempt '\s*\+\s*engine\.attemptCount\s*\+\s*'\)/);
  });
});

describe('spider.js rig-list keyed update', () => {
  // Mirrors the pipeline keyed-update block: a fast-path / slow-path
  // update strategy for the rig-tbody, keyed by data-rig-id on each <tr>.
  // The three mutating <td>s carry per-cell class hooks so updateRigRow
  // can patch them without positional selectors.

  it('createRigRow sets data-rig-id on the <tr>', () => {
    const body = fnBody('createRigRow', /return tr;\s*\}/);
    has(body, /tr\.setAttribute\(['"]data-rig-id['"]\s*,\s*rig\.id\)/);
  });

  it('renderRigList has a fast path that patches in place when order is unchanged', () => {
    const body = fnBody('renderRigList', /\n  \/\/|\n  function /);
    has(body, /getAttribute\(['"]data-rig-id['"]\)/);
    has(body, /orderUnchanged/);
    has(body, /updateRigRow\(/);
  });

  it('exposes updateRigRow(row, rig) for in-place cell updates', () => {
    has(spiderJs, /function updateRigRow\(row, rig\)/);
  });

  it('rig-row cells carry per-cell class hooks for status, cost, and engines', () => {
    // Without class hooks the keyed-update path falls back to positional
    // selectors inside the row — brittle and inconsistent with the
    // pipeline pattern.
    for (const cls of ['rig-row-status', 'rig-row-cost', 'rig-row-engines']) {
      has(spiderJs, new RegExp(`['"]${cls}['"]`));
    }
  });
});

