describe('spider.js session-log lifecycle', () => {
  // T7: an explicit resetSessionLog() helper owns every reset point
  // (engine switch, rig switch, back-to-list) so stale transcripts never
  // leak across contexts and the section stays hidden for non-anima engines.

  it('defines resetSessionLog helper', () => {
    has(spiderJs, /function resetSessionLog\(\)/);
  });

  it('resetSessionLog hides the section, clears the textarea, stops the poll', () => {
    const body = fnBody('resetSessionLog', /\n  \/\/|\n  function /);
    has(body, /stopSessionTranscriptPoll\(/);
    has(body, /session-log-section[\s\S]*?display\s*=\s*['"]none['"]/);
    has(body, /session-log['"][\s\S]*?value\s*=\s*['"]{2}/);
  });

  it('showEngineDetail calls resetSessionLog on engine switch (before render)', () => {
    const body = fnBody('showEngineDetail', /\n  \/\/|\n  function /);
    // Reset must happen before skeleton/render, gated on engineChanged so
    // same-engine re-clicks don't nuke the live poll.
    has(body, /engineChanged[\s\S]*?resetSessionLog\(/);
    const resetIdx = body.indexOf('resetSessionLog(');
    const skeletonIdx = body.indexOf('buildEngineDetailSkeleton(');
    const updateIdx = body.indexOf('updateEngineDetail(');
    assert.ok(resetIdx >= 0, 'reset call present');
    assert.ok(skeletonIdx > resetIdx, 'reset before skeleton build');
    assert.ok(updateIdx > resetIdx, 'reset before updateEngineDetail');
  });

  it('showRigDetail calls resetSessionLog before any render or poll start', () => {
    const body = fnBody('showRigDetail');
    has(body, /resetSessionLog\(/);
    const resetIdx = body.indexOf('resetSessionLog(');
    const skelIdx = body.indexOf('buildRigMetaSkeleton(');
    const pollIdx = body.indexOf('startCurrentRigPoll(');
    assert.ok(resetIdx >= 0, 'resetSessionLog call exists');
    assert.ok(skelIdx > resetIdx, 'reset before rig-meta skeleton build');
    assert.ok(pollIdx > resetIdx, 'reset before rig poll start');
  });

  it('backToList calls resetSessionLog', () => {
    has(fnBody('backToList', /\n  \/\/|\n  function /), /resetSessionLog\(/);
  });

  it('transcript polling is driven off the latest attempt sessionId (anima gating)', () => {
    // D4 / D19: engines without a sessionId are non-anima; the session
    // log stays hidden. After the engine-level retry reshape, sessionId
    // lives on attempts[-1] rather than as a scalar on the engine. The
    // updater derives it into attemptSessionId and funnels that into
    // startSessionTranscriptPoll; a null value hides the section.
    has(
      fnBody('updateEngineDetail'),
      /startSessionTranscriptPoll\(attemptSessionId\s*\|\|\s*null\)/,
    );
    has(
      fnBody('startSessionTranscriptPoll'),
      /if\s*\(!sessionId\)[\s\S]*?display\s*=\s*['"]none['"]/,
    );
  });
});

describe('spider.js rigEndTime read order', () => {
  it('rigEndTime prefers rig.terminalAt over engine.completedAt', () => {
    // The helper must consult rig.terminalAt FIRST and return it
    // verbatim when present. Only when terminalAt is absent should it
    // fall back to max(engine.completedAt), and finally to
    // rig.createdAt. This ordering is load-bearing for the dashboard's
    // elapsed/end-time display — a regression here reintroduces the bug
    // where the timestamp shown in the UI drifts with every
    // engine.completedAt update.
    const body = fnBody('rigEndTime', /\n  \}/);
    // First statement after the function declaration must be the
    // terminalAt short-circuit.
    has(body, /^function rigEndTime\(rig\)\s*\{\s*if\s*\(rig\.terminalAt\)\s*return\s+rig\.terminalAt\s*;/);
    // Sanity: the fallbacks still exist.
    has(body, /engines\s*=\s*rig\.engines/);
    has(body, /maxEndedAt\s*\|\|\s*rig\.createdAt/);
  });
});

describe('Animator pause banner', () => {
  it('declares the banner element at the top of <main> above the tab bar', () => {
    // Banner must be a sibling of the tab bar, rendered ABOVE it inside
    // <main> so it is visible on every tab (D21).
    const bannerIdx = indexHtml.indexOf('id="animator-pause-banner"');
    const tabBarIdx = indexHtml.indexOf('class="tab-bar"');
    assert.ok(bannerIdx > 0, 'banner element exists');
    assert.ok(tabBarIdx > 0, 'tab-bar exists');
    assert.ok(bannerIdx < tabBarIdx, 'banner declared before the tab bar');
  });

  it('is hidden by default via inline style', () => {
    has(indexHtml, /id="animator-pause-banner"[^>]*style="display:none"/);
  });

  it('carries role=status with aria-live=polite', () => {
    has(indexHtml, /id="animator-pause-banner"[^>]*role="status"/);
    has(indexHtml, /id="animator-pause-banner"[^>]*aria-live="polite"/);
  });

  it('has a CSS rule for .animator-pause-banner', () => {
    has(spiderCss, /\.animator-pause-banner\s*\{/);
  });

  it('spider.js declares an independent status-poll timer', () => {
    has(spiderJs, /var ANIMATOR_STATUS_POLL_INTERVAL/);
    has(spiderJs, /function fetchAnimatorStatus\(\)/);
    has(spiderJs, /'\/api\/animator\/status'/);
  });

  it('status poll fires on DOMContentLoaded regardless of rig activity', () => {
    // startAnimatorStatusPoll is called unconditionally in init — not
    // gated on rigs.some(isRigInFlight).
    has(spiderJs, /startAnimatorStatusPoll\(\)/);
  });

  it('banner gates on the server-supplied dispatchable boolean', () => {
    // renderAnimatorBanner gates display on the `dispatchable` field
    // that the `animator-status` tool / route computes from the
    // canonical isDispatchable(doc) helper. Hand-composing the
    // predicate in the browser would re-introduce the duplication that
    // the consolidation commission removes.
    has(spiderJs, /status\.dispatchable/);
    // Fail-closed-hide: a missing field is treated as dispatchable
    // (banner hidden). The gate must not be a bare `=== false` check.
    has(spiderJs, /status\.dispatchable\s*!==\s*false/);
    // No fresh hand-composition of the predicate should remain.
    lacks(spiderJs, /status\.state\s*!==\s*['"]paused['"]/);
    lacks(spiderJs, /untilMs\s*<=\s*Date\.now\(\)/);
  });
});

