describe('spider.js — deep-link URL state', () => {
  it('routes URL reads/writes through window.NexusUrl (no inline helpers)', () => {
    // Inline currentUrlParams / updateUrl are gone (commission moix23w5).
    lacks(spiderJs, /function\s+currentUrlParams\s*\(/);
    lacks(spiderJs, /function\s+updateUrl\s*\(/);
    has(spiderJs, /window\.NexusUrl\.read\(\)/);
    has(spiderJs, /window\.NexusUrl\.update\(/);
  });

  it('showRigDetail pushes ?rig=ID via NexusUrl with push: true (D12)', () => {
    const body = fnBody('showRigDetail');
    has(body, /window\.NexusUrl\.update\(\{\s*rig:\s*rig\.id\s*\}\s*,\s*\{\s*push:\s*true\s*\}\)/);
    has(body, /skipUrlPush/);
  });

  it('backToList clears ?rig via NexusUrl with push: true — never history.back (D11)', () => {
    const body = fnBody('backToList');
    has(body, /window\.NexusUrl\.update\(\{\s*rig:\s*null\s*\}\s*,\s*\{\s*push:\s*true\s*\}\)/);
    lacks(body, /history\.back\(/);
  });

  it('a popstate listener routes browser navigation back through the page', () => {
    has(spiderJs, /window\.addEventListener\(\s*['"]popstate['"]/);
    const popstate = spiderJs.match(/addEventListener\(\s*['"]popstate['"][\s\S]*?\}\)/);
    assert.ok(popstate, 'should find popstate handler body');
    has(popstate[0], /readUrlState\(\)/);
    has(popstate[0], /skipUrlPush:\s*true/);
  });

  it('init reads URL state and opens the deep-linked rig after the list lands', () => {
    has(spiderJs, /var\s+initialState\s*=\s*readUrlState\(\)/);
    has(spiderJs, /showRigDetailById\(\s*initialState\.rigId\s*,\s*\{\s*skipUrlPush:\s*true\s*\}\s*\)/);
  });

  it('not-found state preserves the URL param (D16)', () => {
    const body = fnBody('renderRigDetailNotFound');
    // The function itself must not call NexusUrl.update — the URL is
    // left alone so the operator can recover by editing the address bar.
    lacks(body, /NexusUrl\.update/);
    has(body, /No rig with id/);
  });

  it('does not push a tab=… or engine=… URL param (D13/D14 explicit out-of-scope)', () => {
    // Filter-shaped only (D13 narrow reading): the rigs page must
    // never write ?tab= or ?engine= to the URL. Also forbid the legacy
    // updateUrl shape defensively.
    lacks(spiderJs, /NexusUrl\.update\(\{\s*tab:/);
    lacks(spiderJs, /NexusUrl\.update\(\{\s*engine:/);
    lacks(spiderJs, /updateUrl\(\{\s*tab:/);
    lacks(spiderJs, /updateUrl\(\{\s*engine:/);
  });

  it('rigs filter state writes through NexusUrl.update (replace, no push: true)', () => {
    const writer = fnBody('writeRigFiltersToUrl');
    has(writer, /window\.NexusUrl\.update\(\{[\s\S]*?status:[\s\S]*?\}\s*\)/);
    // Filter writes must use replaceState (D5 default) — no push.
    lacks(writer, /push:\s*true/);
    // Each filter key the rigs page tracks must appear in the writer.
    for (const key of ['status', "'writ-filter'", 'from', 'to', 'sort', 'dir']) {
      has(writer, new RegExp(`${key.replace(/'/g, "\\'")}\\s*:`));
    }
  });

  it('readUrlState validates filter values and surfaces fail-loud errors (D6)', () => {
    const reader = fnBody('readUrlState');
    has(reader, /showUrlError\(/);
    has(reader, /STATUS_VALUES\.indexOf/);
    has(reader, /SORT_FIELDS\.indexOf/);
  });
});
